revision_guidance:
{
  "overall_direction": "Keep the planning/decomposition strengths, but make the skill more execution-grounded at the tool-surface level and more explicit about the final synthesis step. The main gap is not broad structure; it is that plans can still drift into speculative or incomplete downstream calls, especially when a task requires a precise parameter schema or a concrete final selection rather than just candidate gathering.",
  "keep": [
    {
      "rule": "Split before searching. Break the request into a small set of independent subtasks, then map each subtask to the most relevant source or server.",
      "evidence_case_ids": [
        "game_trends_reddit_001",
        "movie_recommender_001"
      ],
      "why": "Both cases benefited from decomposition, even though the plans still needed sharper grounding."
    },
    {
      "rule": "Parallelize independent lookups. Run separate evidence-gathering tracks at the same time when they do not depend on each other, and reserve sequential steps for true dependencies.",
      "evidence_case_ids": [
        "game_trends_reddit_001"
      ],
      "why": "The task naturally spans multiple independent sources, so parallel evidence gathering remains useful."
    },
    {
      "rule": "Carry intermediates forward. Reuse shortlist results, rankings, overlap sets, or computed metrics in downstream lookups instead of restarting from scratch.",
      "evidence_case_ids": [
        "game_trends_reddit_001"
      ],
      "why": "The mention-count workflow and shortlist-style tasks both need intermediate outputs to drive later steps."
    },
    {
      "rule": "State conditional branches explicitly. If a later query depends on an earlier result, write the dependency into the plan and defer the follow-up until the prerequisite is validated.",
      "evidence_case_ids": [
        "game_trends_reddit_001",
        "movie_recommender_001"
      ],
      "why": "Dependency-aware sequencing is still a core strength and should be preserved."
    },
    {
      "rule": "Cross-check before synthesis. Compare overlapping sources when available, verify constraints against the user’s requirements, and only then draft the final plan or answer.",
      "evidence_case_ids": [
        "game_trends_reddit_001"
      ],
      "why": "Cross-source verification is still valuable, especially for comparison tasks."
    }
  ],
  "remove_or_soften": [
    {
      "rule": "Anchor reference values early. Fetch key counts, thresholds, metadata, time windows, or schema details first so later steps have concrete inputs.",
      "evidence_case_ids": [
        "game_trends_reddit_001"
      ],
      "why": "This is directionally right, but the failure shows that 'early anchoring' is not enough unless the exact tool schema is validated before chaining downstream calls. The current wording can still permit speculative parameter choices.",
      "proposed_replacement": "SOFTEN to: Anchor only the values and parameter names that are confirmed by the tool schema before scheduling dependent calls."
    },
    {
      "rule": "The task asks for a shortlist, overlap set, ranking, or fallback logic, but the plan skips directly to the final enrichment step. Counter-action: Compute the intermediate set or ranking before any downstream retrieval, and validate membership or mismatch status with evidence.",
      "evidence_case_ids": [
        "movie_recommender_001"
      ],
      "why": "This is useful, but it is incomplete for tasks whose end goal is a concrete user-facing selection. The failure mode is not just missing an intermediate set; it is stopping at candidate gathering without a final selection/synthesis step.",
      "proposed_replacement": "SOFTEN to: Compute required intermediates first, then add a final synthesis step that turns retrieved evidence into the concrete output the user asked for."
    },
    {
      "rule": "The response stops early, omits a prerequisite lookup, or fails to satisfy formatting/completeness constraints. Counter-action: Check the output requirements against the planned steps before drafting the final answer, and add any missing validation or formatting step.",
      "evidence_case_ids": [
        "movie_recommender_001"
      ],
      "why": "Keep the completeness check, but narrow it so it explicitly requires a final answer-producing step, not just more retrieval.",
      "proposed_replacement": "SOFTEN to: Check output requirements before drafting the final answer, and ensure the plan includes the final synthesis/formatting step needed to satisfy them."
    }
  ],
  "add_or_sharpen": [
    {
      "rule": "Validate each tool’s parameter schema before planning downstream calls, and use only the exact argument names supported by that server.",
      "evidence_case_ids": [
        "game_trends_reddit_001"
      ],
      "section": "Failure lessons"
    },
    {
      "rule": "When a task requires a concrete selection, add an explicit final synthesis step that chooses the requested items and writes the user-facing answer with evidence, not just candidate retrieval.",
      "evidence_case_ids": [
        "movie_recommender_001"
      ],
      "section": "Successful experiences"
    },
    {
      "rule": "For mention-count or thread-follow-up workflows, ground the chain in a validated top item ID before fetching comments or details.",
      "evidence_case_ids": [
        "game_trends_reddit_001"
      ],
      "section": "Failure lessons"
    }
  ],
  "length_budget_note": "The body can stay within budget, but it should be tightened by replacing broad completion language with two sharper rules about schema validation and final synthesis."
}
